command:
$ErrorActionPreference="Stop"
$repo="C:\\dev\\flyExplorer"
$candidate="d004d7ce1b1872f1c18514d9e78b9de88054e364"
$branch="work/current-release-packaging-20261005"
$release=Join-Path $repo "out\\winui\\Release"
$expectedDigest="d82df82738a01f8e7ef61d55c62594bd8c226252e17f3efa40d728a5fd8a2e57"
Write-Host "SHUTDOWN_DIAGNOSTIC_BUILD_OR_PACKAGE=NOT_RUN"
Set-Location -LiteralPath $repo
& git fetch origin $branch --no-tags --prune
if($LASTEXITCODE -ne 0){throw "candidate fetch failed"}
& git cat-file -e "$candidate^{commit}"
if($LASTEXITCODE -ne 0){throw "candidate commit missing"}

if(-not (Test-Path -LiteralPath $release -PathType Container)){
  Write-Host "FAILURE_CATEGORY=REUSED_RUNTIME_UNAVAILABLE"
  throw "No preserved canonical Release runtime; refusing to rebuild for shutdown diagnosis."
}

$badSuffix=@(".pdb",".obj",".lib",".exp",".ilk",".py",".cpp",".h")
$retired=@("flyexplorerwinuishell","phase5","islandbridge","legacy/mfc")
$entries=@()
foreach($file in Get-ChildItem -LiteralPath $release -Recurse -File){
  $rel=$file.FullName.Substring($release.Length).TrimStart([char]92).Replace("\\","/")
  $lower=$rel.ToLowerInvariant()
  if($badSuffix -contains $file.Extension.ToLowerInvariant()){
    Write-Host "FAILURE_CATEGORY=REUSED_RUNTIME_MISMATCH"
    throw "Preserved Release contains non-runtime artifact: $rel"
  }
  foreach($token in $retired){
    if($lower.Contains($token)){
      Write-Host "FAILURE_CATEGORY=REUSED_RUNTIME_MISMATCH"
      throw "Preserved Release contains retired artifact: $rel"
    }
  }
  $entries += [pscustomobject]@{
    Relative=$rel
    SortKey=$lower
    Bytes=$file.Length
    Sha=(Get-FileHash -Algorithm SHA256 -LiteralPath $file.FullName).Hash.ToLowerInvariant()
  }
}
$entries=@($entries | Sort-Object SortKey)
$builder=[Text.StringBuilder]::new()
foreach($entry in $entries){
  [void]$builder.Append($entry.Relative)
  [void]$builder.Append([char]0)
  [void]$builder.Append([string]$entry.Bytes)
  [void]$builder.Append([char]0)
  [void]$builder.Append($entry.Sha)
  [void]$builder.Append([Environment]::NewLine)
}
$sha=[Security.Cryptography.SHA256]::Create()
try{
  $bytes=[Text.Encoding]::UTF8.GetBytes($builder.ToString().Replace("`r`n","`n"))
  $digest=([BitConverter]::ToString($sha.ComputeHash($bytes))).Replace("-","").ToLowerInvariant()
}finally{$sha.Dispose()}
Write-Host "REUSED_RUNTIME_FILES=$($entries.Count)"
Write-Host "REUSED_RUNTIME_MANIFEST_SHA256=$digest"
if($entries.Count -ne 305 -or $digest -ne $expectedDigest){
  Write-Host "FAILURE_CATEGORY=REUSED_RUNTIME_MISMATCH"
  throw "Preserved runtime does not match #358 evidence; refusing to rebuild."
}
Write-Host "REUSED_RUNTIME_MATCH_358=PASS"

$temp=Join-Path $env:RUNNER_TEMP ("shutdown-probe-"+$env:GITHUB_RUN_ID)
if(Test-Path -LiteralPath $temp){Remove-Item -LiteralPath $temp -Recurse -Force}
try{
  & git worktree add --detach $temp $candidate
  if($LASTEXITCODE -ne 0){throw "candidate worktree failed"}
  $env:PYTHONIOENCODING="utf-8"
  & python -X utf8 (Join-Path $temp "tests\\winui\\test_installed_lifecycle.py") --runtime-root $release
  if($LASTEXITCODE -ne 0){throw "isolated shutdown probe failed"}
  Write-Host "SHUTDOWN_DIAGNOSTIC_PASS"
}finally{
  Set-Location -LiteralPath $repo
  if(Test-Path -LiteralPath $temp){& git worktree remove --force $temp}
  & git worktree prune
}
